INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Mainboard immer mit jeder CPU kompatibel ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sockel muss passen"}, {"text": "Ja", "correct": false, "because": "Kompatibilität begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Mainboard für ein IT-System auswähle?', 3, '[{"text": "Chipsatz", "correct": true, "because": "Bestimmt Funktionen"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für ein Mainboard entscheidend?', 5, '[{"text": "CPU-Sockel", "correct": true, "because": "Hält Prozessor"}, {"text": "RAM-Steckplätze", "correct": true, "because": "Für Arbeitsspeicher"}, {"text": "Monitor", "correct": false, "because": "Externes Gerät"}, {"text": "Tastatur", "correct": false, "because": "Peripheriegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Mainboard verbindet alle Komponenten. b) Es hat immer integrierte Grafik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Grafik nicht immer integriert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Mainboard für ein IT-System auswähle?', 4, '[{"text": "PCIe-Steckplätze", "correct": false, "because": "Für Erweiterungen wichtig"}, {"text": "Chipsatz", "correct": false, "because": "Bestimmt Kompatibilität"}, {"text": "Farbschema", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Mainboard ohne BIOS nutzlos ist?', 2, '[{"text": "Ja", "correct": true, "because": "BIOS startet System"}, {"text": "Nein", "correct": false, "because": "BIOS essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich ein Mainboard für ein IT-System auswähle?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnellste Montage", "correct": false, "because": "Sekundär"}, {"text": "Geringes Gewicht", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einem Mainboard für IT-Arbeit entscheidend?', 5, '[{"text": "Anzahl der RAM-Steckplätze", "correct": true, "because": "Beeinflusst Speicher"}, {"text": "PCIe-Version", "correct": true, "because": "Bestimmt Erweiterbarkeit"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Bunte LEDs", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Mainboard hat einen Chipsatz. b) Es ist immer mit WLAN ausgestattet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WLAN nicht immer integriert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich ein Mainboard für ein IT-System auswähle?', 4, '[{"text": "CPU-Sockel", "correct": false, "because": "Für Prozessor nötig"}, {"text": "PCIe-Steckplätze", "correct": false, "because": "Für Erweiterungen"}, {"text": "Designer-Look", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Mainboard ohne Stromversorgung funktionsfähig?', 2, '[{"text": "Nein", "correct": true, "because": "Braucht Energie"}, {"text": "Ja", "correct": false, "because": "Unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein modernes Mainboard?', 4, '[{"text": "Hohe Erweiterbarkeit", "correct": true, "because": "Mehr Steckplätze"}, {"text": "Schnelle Datenübertragung", "correct": true, "because": "Neue Standards"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Mainboards immer eine integrierte GPU haben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht immer integriert"}, {"text": "Ja", "correct": false, "because": "Modellabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Mainboard für Server auszuwählen?', 3, '[{"text": "Hohe RAM-Unterstützung", "correct": true, "because": "Für Server wichtig"}, {"text": "Kleine Größe", "correct": false, "because": "Sekundär"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Mainboard hat einen BIOS-Chip. b) Es ist immer ATX-Größe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einem Mainboard für IT?', 5, '[{"text": "Chipsatz", "correct": true, "because": "Bestimmt Funktionen"}, {"text": "Anschlüsse", "correct": true, "because": "Für Peripherie"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Mainboard für ein IT-System auswähle?', 3, '[{"text": "RAM-Kapazität", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "PCIe-Steckplätze", "correct": false, "because": "Für Erweiterungen"}, {"text": "RGB-Beleuchtung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Mainboard für alle CPUs geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Sockel muss kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Mainboard ohne Chipsatz funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Chipsatz essenziell"}, {"text": "Ja", "correct": false, "because": "Unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend, wenn ich ein Mainboard für IT-Arbeit auswähle?', 4, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnellste Montage", "correct": false, "because": "Sekundär"}, {"text": "Dekoratives Aussehen", "correct": false, "because": "Irrelevant"}]');
